INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_06','V223','Nguyễn Minh',6,'太好了，非常感谢您的帮助！','tài hǎo le， fēi cháng gǎn xiè nín de bāng zhù！','Tuyệt quá, cảm ơn chị nhiều lắm ạ!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT224','S5','Đăng ký thanh toán điện tử, xác thực danh tính','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V224','SIT224','P1','suon_se','tuy_y','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_01','V224','Nguyễn Minh',1,'小杨，我想注册微信支付，还要实名认证对吧？','xiǎo yáng， wǒ xiǎng zhù cè wēi xìn zhī fù， hái yào shí míng rèn zhèng duì ba？','Tiểu Dương ơi, tớ muốn đăng ký WeChat Pay, còn phải xác thực danh tính nữa đúng không?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_02','V224','Bạn (Tiểu Dương)',2,'对呀，不认证没法扫码付钱、转账的。','duì ya， bù rèn zhèng méi fǎ sǎo mǎ fù qián、 zhuǎn zhàng de。','Đúng rồi đó, không xác thực thì không quét mã trả tiền hay chuyển khoản được đâu.','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_03','V224','Nguyễn Minh',3,'那留学生用护照也能认证吗？我没有身份证呢。','nà liú xué shēng yòng hù zhào yě néng rèn zhèng ma？ wǒ méi yǒu shēn fèn zhèng ne。','Vậy lưu học sinh dùng hộ chiếu xác thực được không? Tớ đâu có chứng minh thư.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_04','V224','Bạn (Tiểu Dương)',4,'可以的！直接选择护照认证，按提示上传照片就行啦。','kě yǐ de！ zhí jiē xuǎn zé hù zhào rèn zhèng， àn tí shì shàng chuán zhào piān jiù xíng la。','Được chứ! Cứ chọn xác thực bằng hộ chiếu, làm theo hướng dẫn tải ảnh lên là xong thôi mà.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_05','V224','Nguyễn Minh',5,'原来这么简单，我马上试试！','yuán lái zhè me jiǎn dān， wǒ mǎ shàng shì shì！','Hóa ra đơn giản vậy thôi à, để tớ thử luôn!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_06','V224','Bạn (Tiểu Dương)',6,'弄不懂随时喊我，我教你哈。','nòng bù dǒng suí shí hǎn wǒ， wǒ jiāo nǐ hā。','Không hiểu gì thì cứ gọi tớ, tớ chỉ cho.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT225','S11','Thanh toán quét mã ở cửa hàng tiện lợi','Thanh toán nhanh bằng ví điện tử khi mua đồ','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V225','SIT225','P1','suon_se','tuy_y','Thanh toán nhanh bằng ví điện tử khi mua đồ',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_01','V225','Nhân viên',1,'一共二十五元，你扫码支付就可以啦。','yī gòng èr shí wǔ yuán， nǐ sǎo mǎ zhī fù jiù kě yǐ la。','Tổng cộng hai mươi lăm tệ, anh quét mã thanh toán là được nha.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_02','V225','Nguyễn Minh',2,'好的，我打开微信二维码，您扫我吧？','hǎo de， wǒ dǎ kāi wēi xìn èr wéi mǎ， nín sǎo wǒ ba？','Vâng, em mở mã QR WeChat đây, chị quét cho em nhé?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_03','V225','Nhân viên',3,'可以的，或者你扫收银台的码也行哦。','kě yǐ de， huò zhě nǐ sǎo shōu yín tái de mǎ yě xíng ó。','Được đó, hoặc anh quét mã ở quầy thu ngân cũng được nha.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_04','V225','Nguyễn Minh',4,'我扫好了，支付成功了，您看一下！','wǒ sǎo hǎo le， zhī fù chéng gōng le， nín kàn yī xià！','Em quét xong rồi, thanh toán thành công rồi, chị xem lại giúp em nhé!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_05','V225','Nhân viên',5,'收到啦，没问题！东西拿好，慢走哈。','shōu dào la， méi wèn tí！ dōng xī ná hǎo， màn zǒu hā。','Nhận được rồi nè, không vấn đề gì! Anh cầm đồ cẩn thận, đi cẩn thận nha.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_06','V225','Nguyễn Minh',6,'谢谢！','xiè xiè！','Cảm ơn chị!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT226','S8','Báo danh văn phòng sinh viên quốc tế','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V226','SIT226','P1','suon_se','ban_chinh_thuc','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_01','V226','Nguyễn Minh',1,'老师您好，我是新生阮明，今天来国际学生办公室报到。','lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， jīn tiān lái guó jì xué shēng bàn gōng shì bào dào。','Chào cô/thầy, em là sinh viên mới Nguyễn Minh, hôm nay em đến văn phòng sinh viên quốc tế để báo danh ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_02','V226','Cán bộ',2,'你好！麻烦提交一下你的护照、签证和录取通知书哦。','nǐ hǎo！ má fán tí jiāo yī xià nǐ de hù zhào、 qiān zhèng hé lù qǔ tōng zhī shū ó。','Chào em! Phiền em nộp giúp hộ chiếu, visa và giấy báo nhập học nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_03','V226','Nguyễn Minh',3,'好的，这是我的全部材料，您查收一下。','hǎo de， zhè shì wǒ de quán bù cái liào， nín chá shōu yī xià。','Dạ vâng, đây là toàn bộ giấy tờ của em, cô/thầy kiểm tra giúp em ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_04','V226','Cán bộ',4,'材料齐全无误，这边帮你完成新生注册啦。','cái liào qí quán wú wù， zhè biān bāng nǐ wán chéng xīn shēng zhù cè la。','Giấy tờ đầy đủ và chính xác rồi, để cô/thầy hoàn tất đăng ký sinh viên mới cho em nhé.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_05','V226','Nguyễn Minh',5,'请问接下来还有其他报到流程吗？','qǐng wèn jiē xià lái hái yǒu qí tā bào dào liú chéng ma？','Cho em hỏi sau đó còn thủ tục báo danh nào khác không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_06','V226','Cán bộ',6,'基本完成了，后续选课、体检通知会统一发群里呢。','jī běn wán chéng le， hòu xù xuǎn kè、 tǐ jiǎn tōng zhī huì tǒng yī fā qún lǐ ne。','Cơ bản là xong rồi, sau này thông báo chọn môn học và khám sức khỏe sẽ được đăng chung trong nhóm nhé.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_07','V226','Nguyễn Minh',7,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn cô/thầy!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT227','S8','Thiếu giấy tờ, xin nộp bổ sung','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V227','SIT227','P1','twist','ban_chinh_thuc','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','新生报到材料缺失，多数学校允许限期补交，态度诚恳致歉即可，无需过度紧张；线上截图、电子版打印件大多不具备归档效力，必须纸质复印件。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_01','V227','老师',1,'同学你先坐，我们核对一下新生报到需要提交的全套材料。','tóng xué nǐ xiān zuò， wǒ men hé duì yī xià xīn shēng bào dào xū yào tí jiāo de quán tào cái liào。','Em ngồi xuống đi, chúng ta kiểm tra lại toàn bộ giấy tờ cần nộp khi báo danh sinh viên mới nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_02','V227','阮明',2,'好的老师，我把手里的文件都拿出来给您核对。','hǎo de lǎo shī， wǒ bǎ shǒu lǐ de wén jiàn dōu ná chū lái gěi nín hé duì。','Dạ vâng thưa cô/thầy, em lấy hết giấy tờ trong tay ra để cô/thầy kiểm tra ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_03','V227','老师',3,'毕业证复印件、签证页、体检表都齐了，还差一份疫苗接种证明，你带过来了吗？','bì yè zhèng fù yìn jiàn、 qiān zhèng yè、 tǐ jiǎn biǎo dōu qí le， hái chà yī fèn yì miáo jiē zhǒng zhèng míng， nǐ dài guò lái le ma？','Bản sao bằng tốt nghiệp, trang visa, phiếu khám sức khỏe đều đủ rồi, còn thiếu giấy chứng nhận tiêm vaccine, em có mang theo không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_04','V227','阮明',4,'不好意思老师，出门收拾行李的时候漏掉这份材料，我完全忘记带了，非常抱歉。','bù hǎo yì sī lǎo shī， chū mén shōu shí xíng lǐ de shí hòu lòu diào zhè fèn cái liào， wǒ wán quán wàng jì dài le， fēi cháng bào qiàn。','Em xin lỗi thầy/cô, lúc thu dọn hành lý em quên mất giấy này, em hoàn toàn quên mang theo, thật sự xin lỗi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_05','V227','老师',5,'没事的，不用紧张，很多新生都会出现材料遗漏的情况。','méi shì de， bù yòng jǐn zhāng， hěn duō xīn shēng dōu huì chū xiàn cái liào yí lòu de qíng kuàng。','Không sao đâu, em đừng lo lắng, nhiều sinh viên mới cũng gặp tình trạng thiếu giấy tờ như vậy mà.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_06','V227','阮明',6,'我心里特别着急，怕耽误今天的新生登记流程，影响后续选课住宿。','wǒ xīn lǐ tè bié zháo jí， pà dān wù jīn tiān de xīn shēng dēng jì liú chéng， yǐng xiǎng hòu xù xuǎn kè zhù sù。','Em thấy rất lo trong lòng, sợ làm chậm trễ thủ tục đăng ký sinh viên mới hôm nay, ảnh hưởng đến việc chọn môn và chỗ ở sau này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_07','V227','老师',7,'我先跟你说明学校的规定，所有材料必须完整归档，不能长期缺件。','wǒ xiān gēn nǐ shuō míng xué xiào de guī dìng， suǒ yǒu cái liào bì xū wán zhěng guī dàng， bù néng cháng qī quē jiàn。','Cô/thầy nói trước với em quy định của trường là tất cả giấy tờ phải nộp đầy đủ, không được thiếu lâu dài.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_08','V227','阮明',8,'那请问我明天补交可以吗？明天补交完整不会影响我的新生报到手续吧？','nà qǐng wèn wǒ míng tiān bǔ jiāo kě yǐ ma？ míng tiān bǔ jiāo wán zhěng bú huì yǐng xiǎng wǒ de xīn shēng bào dào shǒu xù ba？','Vậy cho em hỏi ngày mai em nộp bổ sung có được không ạ? Nộp bổ sung đầy đủ vào ngày mai thì không ảnh hưởng đến thủ tục báo danh của em chứ ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_09','V227','老师',9,'正常截止时间是今天下午五点，严格来说逾期不予受理，不过可以给你特殊放宽一天。','zhèng cháng jié zhǐ shí jiān shì jīn tiān xià wǔ wǔ diǎn， yán gé lái shuō yú qī bù yǔ shòu lǐ， bù guò kě yǐ gěi nǐ tè shū fàng kuān yī tiān。','Thời hạn bình thường là năm giờ chiều nay, nói đúng ra thì quá hạn sẽ không được tiếp nhận, nhưng cô/thầy có thể linh động cho em thêm một ngày.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_10','V227','阮明',10,'太感谢老师愿意通融，我明天一早就回家找出证明，复印完整送过来。','tài gǎn xiè lǎo shī yuàn yì tōng róng， wǒ míng tiān yī zǎo jiù huí jiā zhǎo chū zhèng míng， fù yìn wán zhěng sòng guò lái。','Em cảm ơn thầy/cô đã thông cảm nhiều lắm ạ, sáng sớm mai em sẽ về nhà tìm giấy chứng nhận, photo đầy đủ rồi mang đến ngay.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_11','V227','老师',11,'记住一定要带纸质原件复印件，照片截图打印出来是不被认可的。','jì zhù yí dìng yào dài zhǐ zhì yuán jiàn fù yìn jiàn， zhào piān jié tú dǎ yìn chū lái shì bù bèi rèn kě de。','Em nhớ nhé, nhất định phải mang bản gốc giấy và bản photo, ảnh chụp màn hình in ra thì không được chấp nhận đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_12','V227','阮明',12,'我记下这条要求了，明天一定准备规范的纸质文件。','wǒ jì xià zhè tiáo yāo qiú le， míng tiān yí dìng zhǔn bèi guī fàn de zhǐ zhì wén jiàn。','Em ghi nhớ yêu cầu này rồi ạ, ngày mai nhất định em sẽ chuẩn bị giấy tờ đúng chuẩn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_13','V227','老师',13,'行，我先把你现有材料临时存档，等你补齐再统一录入系统。','xíng， wǒ xiān bǎ nǐ xiàn yǒu cái liào lín shí cún dàng， děng nǐ bǔ qí zài tǒng yī lù rù xì tǒng。','Được rồi, trước mắt cô/thầy sẽ lưu tạm hồ sơ hiện có của em, đợi em bổ sung đầy đủ rồi nhập vào hệ thống một thể.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_14','V227','阮明',14,'给老师增添额外工作量实在不好意思，我明天准时送来！','gěi lǎo shī zēng tiān é wài gōng zuò liàng shí zài bù hǎo yì sī， wǒ míng tiān zhǔn shí sòng lái！','Em thật sự áy náy vì làm phiền thầy/cô thêm việc, ngày mai em sẽ mang đến đúng giờ ạ!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT228','S9','Chọn môn, lớp đã đầy phải đổi lớp','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V228','SIT228','P1','that_bai_nhe','ban_chinh_thuc','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','Lớp học đông theo nguyên tắc đăng ký trước được trước; lớp đầy thì chỉ có thể đổi sang lớp/giờ khác, không thể xin thêm suất.') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_01','V228','Nguyễn Minh',1,'老师您好，我想选的汉语课已经显示满员了。','lǎo shī nín hǎo， wǒ xiǎng xuǎn de hàn yǔ kè yǐ jīng xiǎn shì mǎn yuán le。','Chào cô/thầy, môn tiếng Hán em muốn chọn đã báo đầy lớp rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_02','V228','Giáo vụ',2,'是的，这个热门班级名额已经抢完了呢。','shì de， zhè ge rè mén bān jí míng é yǐ jīng qiǎng wán le ne。','Đúng vậy, lớp hot này hết chỗ nhanh lắm đó.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_03','V228','Nguyễn Minh',3,'那请问我能不能换到其他时间段的班级呀？','nà qǐng wèn wǒ néng bù néng huàn dào qí tā shí jiān duàn de bān jí ya？','Vậy cho em hỏi em có thể đổi sang lớp học vào khung giờ khác không ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_04','V228','Giáo vụ',4,'可以的，还有周三下午的班级有空位，内容是一样的。','kě yǐ de， hái yǒu zhōu sān xià wǔ de bān jí yǒu kòng wèi， nèi róng shì yī yàng de。','Được chứ, còn lớp chiều thứ Tư vẫn còn chỗ trống, nội dung học hoàn toàn giống nhau.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_05','V228','Nguyễn Minh',5,'那就太好了！我直接改选这个班级就可以吧？','nà jiù tài hǎo le！ wǒ zhí jiē gǎi xuǎn zhè ge bān jí jiù kě yǐ ba？','Vậy thì tốt quá ạ! Em cứ trực tiếp đổi sang lớp này là được đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_06','V228','Giáo vụ',6,'对的，系统直接操作就行，不用额外申请。','duì de， xì tǒng zhí jiē cāo zuò jiù xíng， bù yòng é wài shēn qǐng。','Đúng rồi, em thao tác ngay trên hệ thống là được, không cần xin thêm gì cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT229','S9','Gặp cố vấn học tập lần đầu','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V229','SIT229','P1','suon_se','ban_chinh_thuc','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','Giảng viên hướng dẫn học tập sẵn sàng tư vấn chọn môn; sinh viên nên chủ động hỏi ngay từ buổi gặp đầu tiên.') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_01','V229','Nguyễn Minh',1,'张老师您好，我是新生阮明，来自越南，很高兴成为您的学生。','zhāng lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， lái zì yuè nán， hěn gāo xìng chéng wéi nín de xué shēng。','Chào cô Trương, em là sinh viên mới Nguyễn Minh, đến từ Việt Nam, em rất vui được làm học trò của cô ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_02','V229','Cố vấn',2,'你好！欢迎你来本校就读，适应这边的生活了吗？','nǐ hǎo！ huān yíng nǐ lái běn xiào jiù dú， shì yìng zhè biān de shēng huó le ma？','Chào em! Chào mừng em đến học tại trường mình, em đã quen với cuộc sống ở đây chưa?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_03','V229','Nguyễn Minh',3,'慢慢适应啦，我想咨询一下，本专业选课有什么侧重点呢？','màn màn shì yìng la， wǒ xiǎng zī xún yī xià， běn zhuān yè xuǎn kè yǒu shén me cè zhòng diǎn ne？','Em đang dần quen ạ, em muốn hỏi cô một chút, chọn môn học của ngành mình thì nên chú trọng vào điểm nào ạ?','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_04','V229','Cố vấn',4,'优先选专业基础课，选修课可以选贴合国际贸易的课程哦。','yōu xiān xuǎn zhuān yè jī chǔ kè， xuǎn xiū kè kě yǐ xuǎn tiē hé guó jì mào yì de kè chéng ó。','Ưu tiên chọn các môn cơ sở chuyên ngành trước, môn tự chọn thì em nên chọn những môn liên quan đến thương mại quốc tế nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_05','V229','Nguyễn Minh',5,'好的，那大一需要多选公共课吗？','hǎo de， nà dà yī xū yào duō xuǎn gōng gòng kè ma？','Dạ vâng, vậy năm nhất có cần chọn nhiều môn đại cương không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_06','V229','Cố vấn',6,'适当选择即可，不用选课太多，避免压力过大哈。','shì dàng xuǎn zé jí kě， bù yòng xuǎn kè tài duō， bì miǎn yā lì guò dà hā。','Chọn vừa phải thôi, không cần chọn quá nhiều, tránh áp lực quá lớn nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_07','V229','Nguyễn Minh',7,'我明白了，谢谢老师指导！','wǒ míng bái le， xiè xiè lǎo shī zhǐ dǎo！','Em hiểu rồi ạ, em cảm ơn cô đã hướng dẫn!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT230','S9','Chụp ảnh làm thẻ sinh viên','Chụp ảnh đơn giản để làm thẻ sinh viên','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V230','SIT230','P1','suon_se','tuy_y','Chụp ảnh đơn giản để làm thẻ sinh viên',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_01','V230','Nhân viên',1,'同学，过来拍学生证照片啦。','tóng xué， guò lái pāi xué shēng zhèng zhào piān la。','Em ơi, qua đây chụp ảnh làm thẻ sinh viên nào.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Dạ vâng, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em không rõ lắm.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản thôi, không đội mũ, không đeo kính râm, để lộ trán ra là được.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Vâng, em chỉnh lại một chút, thế này được chưa ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Giữ nụ cười, nhìn vào ống kính, xong ngay đây.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là có thể làm thẻ sinh viên luôn được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng vậy, ảnh sẽ được nhập vào hệ thống, một tuần sau là lấy thẻ được rồi.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Chào cô/thầy, em là sinh viên mới, em muốn làm thẻ thư viện ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được, em đưa thẻ sinh viên ra là làm miễn phí luôn nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Dạ đây ạ, làm xong thì mỗi lần em mượn được bao nhiêu cuốn ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Sinh viên quốc tế mỗi lần được mượn mười cuốn, thời hạn mượn là ba mươi ngày nhé.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_05','V231','Nguyễn Minh',5,'那我借这本汉语教材可以吧？','nà wǒ jiè zhè běn hàn yǔ jiào cái kě yǐ ba？','Vậy em mượn cuốn giáo trình tiếng Hán này được không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_06','V231','Thủ thư',6,'没问题，我帮你扫码登记，已经借阅成功啦。','méi wèn tí， wǒ bāng nǐ sǎo mǎ dēng jì， yǐ jīng jiè yuè chéng gōng la。','Không vấn đề gì, để cô/thầy quét mã đăng ký giúp em, mượn thành công rồi đó.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_07','V231','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô/thầy nhiều ạ!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT232','S9','Đổi mật khẩu email trường','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V232','SIT232','P1','twist','tuy_y','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','Tài khoản hệ thống trường phân biệt chữ hoa/thường trong mật khẩu; cần đổi mật khẩu ban đầu ngay lần đăng nhập đầu.') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_01','V232','Nguyễn Minh',1,'宇哥，学校邮箱我登不上，初始密码不对呢。','yǔ gē， xué xiào yóu xiāng wǒ dēng bù shàng， chū shǐ mì mǎ bú duì ne。','Anh Vũ ơi, em đăng nhập không được vào email của trường, mật khẩu ban đầu bị sai rồi.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_02','V232','Trần Vũ',2,'是吗？你是不是输错大小写了呀？','shì ma？ nǐ shì bú shì shū cuò dà xiǎo xiě le ya？','Vậy à? Có phải em gõ sai chữ hoa chữ thường không?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_03','V232','Nguyễn Minh',3,'有可能！我一直没注意大小写区分。','yǒu kě néng！ wǒ yì zhí méi zhù yì dà xiǎo xiě qū fēn。','Có thể lắm! Em cứ không để ý phân biệt chữ hoa chữ thường.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_04','V232','Trần Vũ',4,'没事，我教你，重新输入区分大小写就能登上啦。','méi shì， wǒ jiāo nǐ， chóng xīn shū rù qū fēn dà xiǎo xiě jiù néng dēng shàng la。','Không sao, anh chỉ cho, gõ lại phân biệt hoa thường là đăng nhập được ngay thôi.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_05','V232','Nguyễn Minh',5,'登上了！接下来怎么修改密码呀？','dēng shàng le！ jiē xià lái zěn me xiū gǎi mì mǎ ya？','Đăng nhập được rồi! Tiếp theo đổi mật khẩu như thế nào vậy anh?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_06','V232','Trần Vũ',6,'在个人中心设置新密码，记得设置复杂一点哦。','zài gè rén zhōng xīn shè zhì xīn mì mǎ， jì de shè zhì fù zá yì diǎn ó。','Vào trang cá nhân đặt mật khẩu mới, nhớ đặt phức tạp một chút nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_07','V232','Nguyễn Minh',7,'好嘞，我马上改，太谢谢你啦！','hǎo lei， wǒ mǎ shàng gǎi， tài xiè xiè nǐ la！','Dạ được, em đổi ngay đây, cảm ơn anh nhiều lắm!','AM08') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT233','S9','Nộp bài trên LMS gặp lỗi hệ thống','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V233','SIT233','P1','that_bai_nhe','ban_chinh_thuc','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','Sự cố kỹ thuật trên hệ thống học tập thường được nhà trường tự động gia hạn, không cần làm đơn xin riêng.') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_01','V233','Nguyễn Minh',1,'助教您好，我在教学平台提交作业，一直提交失败呢。','zhù jiào nín hǎo， wǒ zài jiào xué píng tái tí jiāo zuò yè， yì zhí tí jiāo shī bài ne。','Chào trợ giảng, em nộp bài trên hệ thống học tập mà cứ nộp không được ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_02','V233','Trợ giảng',2,'是文件上传不了，还是页面卡顿呀？','shì wén jiàn shàng chuán bù liǎo， hái shì yè miàn kǎ dùn ya？','Là file không tải lên được, hay là trang bị đứng vậy?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_03','V233','Nguyễn Minh',3,'页面一直加载，点提交没有任何反应。','yè miàn yì zhí jiā zài， diǎn tí jiāo méi yǒu rèn hé fǎn yìng。','Trang cứ load mãi, bấm nộp bài không có phản hồi gì cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_04','V233','Trợ giảng',4,'应该是平台晚间系统卡顿，今天很多同学都遇到了。','yīng gāi shì píng tái wǎn jiān xì tǒng kǎ dùn， jīn tiān hěn duō tóng xué dōu yù dào le。','Chắc là do hệ thống bị lag vào buổi tối, hôm nay rất nhiều bạn cũng gặp phải tình trạng này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_05','V233','Nguyễn Minh',5,'那我的作业会不会逾期扣分啊？','nà wǒ de zuò yè huì bú huì yú qī kòu fēn a？','Vậy bài của em có bị trừ điểm vì nộp trễ không ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_06','V233','Trợ giảng',6,'不会的，系统问题统一延后提交，明天早上再交就行哈。','bú huì de， xì tǒng wèn tí tǒng yī yán hòu tí jiāo， míng tiān zǎo shàng zài jiāo jiù xíng hā。','Không đâu, lỗi hệ thống thì sẽ gia hạn nộp bài chung cho cả lớp, sáng mai nộp lại là được nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_07','V233','Nguyễn Minh',7,'太好了，谢谢您告诉我！','tài hǎo le， xiè xiè nín gào sù wǒ！','Tuyệt quá, em cảm ơn trợ giảng đã báo cho em biết!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT234','S10','Hỏi phạm vi bảo hiểm y tế sinh viên','Hỏi rõ phạm vi được và không được bảo hiểm chi trả','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V234','SIT234','P1','suon_se','ban_chinh_thuc','Hỏi rõ phạm vi được và không được bảo hiểm chi trả',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_01','V234','Nguyễn Minh',1,'老师您好，我想咨询一下留学生医保的报销范围呢。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià liú xué shēng yī bǎo de bào xiāo fàn wéi ne。','Chào thầy/cô, em muốn hỏi về phạm vi thanh toán bảo hiểm y tế cho lưu học sinh ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_02','V234','Cán bộ',2,'没问题，学校医保主要报销公立医院的门诊和住院费用哦。','méi wèn tí， xué xiào yī bǎo zhǔ yào bào xiāo gōng lì yī yuàn de mén zhěn hé zhù yuàn fèi yòng ó。','Không vấn đề gì, bảo hiểm y tế của trường chủ yếu chi trả cho khám ngoại trú và nội trú tại bệnh viện công đó.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_03','V234','Nguyễn Minh',3,'那感冒、肠胃炎这类普通小病也能报销吧？','nà gǎn mào、 cháng wèi yán zhè lèi pǔ tōng xiǎo bìng yě néng bào xiāo ba？','Vậy những bệnh thông thường như cảm cúm, viêm dạ dày ruột cũng được chi trả chứ ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_04','V234','Cán bộ',4,'可以的，常规疾病都在报销范围内，意外受伤也能理赔。','kě yǐ de， cháng guī jí bìng dōu zài bào xiāo fàn wéi nèi， yì wài shòu shāng yě néng lǐ péi。','Được chứ, các bệnh thông thường đều nằm trong phạm vi chi trả, tai nạn thương tích cũng được bồi thường.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_05','V234','Nguyễn Minh',5,'请问有不能报销的项目吗？','qǐng wèn yǒu bù néng bào xiāo de xiàng mù ma？','Cho em hỏi có những khoản nào không được chi trả không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_06','V234','Cán bộ',6,'私立医院、美容整形、牙科美白这些是不报销的哈。','sī lì yī yuàn、 měi róng zhěng xíng、 yá kē měi bái zhè xiē shì bù bào xiāo de hā。','Bệnh viện tư, thẩm mỹ, làm trắng răng thì không được chi trả nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_07','V234','Nguyễn Minh',7,'我清楚了，谢谢老师详细讲解！','wǒ qīng chǔ le， xiè xiè lǎo shī xiáng xì jiǎng jiě！','Em hiểu rồi ạ, cảm ơn thầy/cô đã giải thích cặn kẽ!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT235','S10','Khám sức khỏe nhập học','Lấy số và điền thông tin cá nhân trước khi khám','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V235','SIT235','P1','suon_se','ban_chinh_thuc','Lấy số và điền thông tin cá nhân trước khi khám','Khám sức khỏe đầu năm là yêu cầu bắt buộc với mọi sinh viên, không riêng sinh viên quốc tế; thông tin sẽ lưu vào hồ sơ sinh viên.') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_01','V235','Nguyễn Minh',1,'您好，我是新生，过来做入学体检，请问怎么办理呀？','nín hǎo， wǒ shì xīn shēng， guò lái zuò rù xué tǐ jiǎn， qǐng wèn zěn me bàn lǐ ya？','Chào anh/chị, em là sinh viên mới, đến khám sức khỏe nhập học, cho em hỏi làm thủ tục thế nào ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_02','V235','Nhân viên',2,'先在自助机取个体检号，再填写这份个人信息表哦。','xiān zài zì zhù jī qǔ gè tǐ jiǎn hào， zài tián xiě zhè fèn gè rén xìn xī biǎo ó。','Em lấy số khám ở máy tự phục vụ trước, rồi điền vào tờ thông tin cá nhân này nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_03','V235','Nguyễn Minh',3,'好的，表格里的国籍和证件类型如实填写就可以吧？','hǎo de， biǎo gé lǐ de guó jí hé zhèng jiàn lèi xíng rú shí tián xiě jiù kě yǐ ba？','Vâng ạ, phần quốc tịch và loại giấy tờ trong biểu mẫu cứ điền đúng sự thật là được đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_04','V235','Nhân viên',4,'对的，信息全部填准确，避免体检单出错呢。','duì de， xìn xī quán bù tián zhǔn què， bì miǎn tǐ jiǎn dān chū cuò ne。','Đúng vậy, thông tin phải điền chính xác hết, tránh để phiếu khám bị sai đó.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_05','V235','Nguyễn Minh',5,'表格填完、号也取好了，接下来做什么？','biǎo gé tián wán、 hào yě qǔ hǎo le， jiē xià lái zuò shén me？','Em điền xong biểu mẫu và lấy số rồi, tiếp theo làm gì ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_06','V235','Nhân viên',6,'拿着单据依次做各项检查就行，流程很简单的哈。','ná zhe dān jù yī cì zuò gè xiàng jiǎn chá jiù xíng， liú chéng hěn jiǎn dān de hā。','Em cầm phiếu đi khám lần lượt các mục là được, quy trình đơn giản lắm nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_07','V235','Nguyễn Minh',7,'明白了，谢谢您！','míng bái le， xiè xiè nín！','Em hiểu rồi ạ, cảm ơn anh/chị!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT236','S2','Tắc đường, xin đổi lộ trình vì sắp trễ học','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V236','SIT236','P1','twist','tuy_y','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','早高峰城市主干道普遍拥堵，乘客可礼貌请求司机绕路，司机一般会主动配合，不会额外加价；支路人流密集，司机通常会减速慢行保障安全。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_01','V236','司机',1,'小伙子，跟你说一下，前方主干道早高峰全线拥堵，车速特别慢哦。','xiǎo huǒ zi， gēn nǐ shuō yī xià， qián fāng zhǔ gàn dào zǎo gāo fēng quán xiàn yōng dǔ， chē sù tè bié màn ó。','Cậu ơi, tôi báo trước, đường chính phía trước đang tắc nghẽn toàn tuyến giờ cao điểm, xe chạy chậm lắm đó.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_02','V236','阮明',2,'师傅，我上午有专业课，还有十分钟就要上课，再堵下去肯定要迟到了呢！','shī fù， wǒ shàng wǔ yǒu zhuān yè kè， hái yǒu shí fēn zhōng jiù yào shàng kè， zài dǔ xià qù kěn dìng yào chí dào le ne！','Bác tài ơi, sáng nay em có tiết chuyên ngành, chỉ còn mười phút nữa là vào học, cứ tắc thế này chắc chắn trễ mất!','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_03','V236','司机',3,'我打开导航看看路况，主干道三条车道全部堵死，短时间疏通不开。','wǒ dǎ kāi dǎo háng kàn kàn lù kuàng， zhǔ gàn dào sān tiáo chē dào quán bù dǔ sǐ， duǎn shí jiān shū tōng bù kāi。','Để tôi mở bản đồ xem tình hình đường xá, ba làn đường chính đều tắc cứng, khó thông trong thời gian ngắn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_04','V236','阮明',4,'那有没有别的小路可以绕一下，只要能赶在上课前到学校就行呀？','nà yǒu méi yǒu bié de xiǎo lù kě yǐ rào yī xià， zhǐ yào néng gǎn zài shàng kè qián dào xué xiào jiù xíng ya？','Vậy có đường nhỏ nào đi vòng được không ạ, chỉ cần kịp tới trường trước giờ học là được rồi?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_05','V236','司机',5,'倒是有一条居民区小路能绕行，唯一问题是路程会多两公里，稍微远一点。','dǎo shì yǒu yī tiáo jū mín qū xiǎo lù néng rào xíng， wéi yī wèn tí shì lù chéng huì duō liǎng gōng lǐ， shāo wēi yuǎn yì diǎn。','Cũng có một con đường nhỏ trong khu dân cư đi vòng được, chỉ có điều là xa hơn hai cây số, hơi vòng một chút.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_06','V236','阮明',6,'没关系的，多绕一点路完全没问题，只要别耽误上课就好，麻烦您绕路啦！','méi guān xì de， duō rào yì diǎn lù wán quán méi wèn tí， zhǐ yào bié dān wù shàng kè jiù hǎo， má fán nín rào lù la！','Không sao đâu ạ, đi vòng thêm chút cũng được, miễn đừng trễ học là được rồi, phiền bác tài đi vòng giúp em nhé!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_07','V236','司机',7,'绕行小路里面行人、电动车多，车速提不上来，最多只能匀速慢慢开。','rào xíng xiǎo lù lǐ miàn xíng rén、 diàn dòng chē duō， chē sù tí bù shàng lái， zuì duō zhǐ néng yún sù màn màn kāi。','Đường nhỏ đi vòng đó nhiều người đi bộ với xe điện lắm, không chạy nhanh được, chỉ có thể đi đều đều thôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_08','V236','阮明',8,'我能理解，安全第一，只要能避开主干道的长堵车我就很满足。','wǒ néng lǐ jiě， ān quán dì yī， zhǐ yào néng bì kāi zhǔ gàn dào de zhǎng dǔ chē wǒ jiù hěn mǎn zú。','Em hiểu mà, an toàn là trên hết, chỉ cần tránh được đoạn tắc dài trên đường chính là em thấy ổn rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_09','V236','司机',9,'没问题，我现在立刻变道下高架，转入旁边的支路绕行。','méi wèn tí， wǒ xiàn zài lì kè biàn dào xià gāo jià， zhuǎn rù páng biān de zhī lù rào xíng。','Được rồi, giờ tôi chuyển làn xuống cầu vượt ngay, rẽ vào đường nhánh bên cạnh để đi vòng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_10','V236','阮明',10,'大概还需要几分钟能抵达学校校门，我心里好有个数。','dà gài hái xū yào jǐ fēn zhōng néng dǐ dá xué xiào xiào mén， wǒ xīn lǐ hǎo yǒu gè shù。','Khoảng mấy phút nữa thì tới cổng trường ạ, để em còn biết mà ước lượng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_11','V236','司机',11,'顺利的话七八分钟就能到，比原地干等快二十分钟不止。','shùn lì de huà qī bā fēn zhōng jiù néng dào， bǐ yuán dì gàn děng kuài èr shí fēn zhōng bù zhǐ。','Thuận lợi thì bảy tám phút là tới, nhanh hơn đứng chờ tại chỗ đến gần hai mươi phút đó.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_12','V236','阮明',12,'太好了，这下不用担心迟到被扣平时分，辛苦您特意绕路！','tài hǎo le， zhè xià bù yòng dān xīn chí dào bèi kòu píng shí fēn， xīn kǔ nín tè yì rào lù！','Tuyệt quá, vậy là khỏi lo bị trễ học mà trừ điểm chuyên cần, cảm ơn bác tài đã cố tình đi vòng giúp em!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_13','V236','司机',13,'小事一桩，学生上课要紧，我尽量平稳开车不耽误你。','xiǎo shì yī zhuāng， xué shēng shàng kè yào jǐn， wǒ jǐn liàng píng wěn kāi chē bù dān wù nǐ。','Chuyện nhỏ thôi, sinh viên đi học là quan trọng, tôi sẽ cố lái êm để không làm chậm trễ cậu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_14','V236','阮明',14,'等下车我给您五星好评，真的太感谢您了！','děng xià chē wǒ gěi nín wǔ xīng hǎo píng， zhēn de tài gǎn xiè nín le！','Lát xuống xe em sẽ đánh giá năm sao cho bác, thật sự cảm ơn bác nhiều lắm!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT237','S11','Siêu thị không nhận tiền mặt, phải quét mã','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V237','SIT237','P1','twist','tuy_y','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_01','V237','Thu ngân',1,'一共三十八元，麻烦您结账哦。','yī gòng sān shí bā yuán， má fán nín jié zhàng ó。','Tổng cộng là ba mươi tám tệ, phiền anh/chị thanh toán giúp nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_02','V237','Nguyễn Minh',2,'好的，我给您现金可以吗？我没带手机扫码呢。','hǎo de， wǒ gěi nín xiàn jīn kě yǐ ma？ wǒ méi dài shǒu jī sǎo mǎ ne。','Vâng, em trả tiền mặt được không ạ? Em không mang điện thoại để quét mã.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_03','V237','Thu ngân',3,'不好意思呀，本店现在不收现金，只能微信、支付宝扫码支付。','bù hǎo yì sī ya， běn diàn xiàn zài bù shōu xiàn jīn， zhǐ néng wēi xìn、 zhī fù bǎo sǎo mǎ zhī fù。','Xin lỗi anh/chị nha, cửa hàng hiện giờ không nhận tiền mặt, chỉ nhận quét mã WeChat hoặc Alipay thôi ạ.','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_04','V237','Nguyễn Minh',4,'这样啊，那我现在打开手机马上扫码哈。','zhè yàng a， nà wǒ xiàn zài dǎ kāi shǒu jī mǎ shàng sǎo mǎ hā。','Vậy à, để em lấy điện thoại quét mã ngay đây.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_05','V237','Thu ngân',5,'不急，您慢慢操作，支付成功我就出小票。','bù jí， nín màn màn cāo zuò， zhī fù chéng gōng wǒ jiù chū xiǎo piào。','Không vội đâu, anh/chị cứ từ từ thao tác, thanh toán xong em xuất hóa đơn cho.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_06','V237','Nguyễn Minh',6,'付好啦，谢谢您提醒！','fù hǎo la， xiè xiè nín tí xǐng！','Trả xong rồi nè, cảm ơn bạn đã nhắc nhé!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT238','S7','Máy giặt hỏng, đổi sang máy khác','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V238','SIT238','P1','that_bai_nhe','tuy_y','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_01','V238','Nguyễn Minh',1,'阿姨您好，洗衣房的投币机坏了，投钱没反应呢。','ā yí nín hǎo， xǐ yī fáng de tóu bì jī huài le， tóu qián méi fǎn yìng ne。','Cô ơi, máy giặt bỏ xu ở phòng giặt bị hỏng rồi, bỏ tiền vào không thấy phản ứng gì cả.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_02','V238','Quản lý',2,'是卡住了吗？我过去看一下哦。','shì kǎ zhù le ma？ wǒ guò qù kàn yī xià ó。','Bị kẹt à? Để cô ra xem thử nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_03','V238','Nguyễn Minh',3,'对的，我试了两次都没用，衣服放进去没法洗。','duì de， wǒ shì le liǎng cì dōu méi yòng， yī fú fàng jìn qù méi fǎ xǐ。','Vâng, con thử hai lần rồi mà không được, quần áo bỏ vào không giặt được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_04','V238','Quản lý',4,'这台机器临时故障了，你换旁边那台用就行哈。','zhè tái jī qì lín shí gù zhàng le， nǐ huàn páng biān nà tái yòng jiù xíng hā。','Máy này đang bị hỏng tạm thời, con qua dùng máy bên cạnh là được nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_05','V238','Nguyễn Minh',5,'好的，那故障机器什么时候能修好呀？','hǎo de， nà gù zhàng jī qì shén me shí hòu néng xiū hǎo ya？','Vâng ạ, vậy máy hỏng bao giờ thì sửa được ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_06','V238','Quản lý',6,'明天师傅过来检修，今晚先用别的机器吧。','míng tiān shī fù guò lái jiǎn xiū， jīn wǎn xiān yòng bié de jī qì ba。','Mai thợ sẽ tới sửa, tối nay con cứ dùng tạm máy khác nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_07','V238','Nguyễn Minh',7,'麻烦您了，谢谢阿姨！','má fán nín le， xiè xiè ā yí！','Phiền cô rồi ạ, con cảm ơn cô nhiều!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT239','S3','Đi nhầm chiều tàu điện ngầm','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V239','SIT239','P1','twist','ban_chinh_thuc','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_01','V239','Nguyễn Minh',1,'您好，不好意思打扰您啦！我好像坐错地铁了。','nín hǎo， bù hǎo yì sī dǎ rǎo nín la！ wǒ hǎo xiàng zuò cuò dì tiě le。','Chào chị, cho em xin lỗi làm phiền chị chút ạ! Hình như em lên nhầm chuyến tàu điện ngầm rồi.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_02','V239','Nhân viên nhà ga',2,'没事的啊，别着急，你要去哪里呀？','méi shì de a， bié zháo jí， nǐ yào qù nǎ lǐ ya？','Không sao đâu, đừng lo, em muốn đi đâu vậy?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_03','V239','Nguyễn Minh',3,'我想去大学城校区，刚刚上车坐反方向了，现在不知道怎么换乘呢。','wǒ xiǎng qù dà xué chéng xiào qū， gāng gāng shàng chē zuò fǎn fāng xiàng le， xiàn zài bù zhī dào zěn me huàn chéng ne。','Em muốn đến khu Đại học thành, vừa lên tàu lại đi ngược chiều mất rồi, giờ không biết đổi tàu thế nào ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_04','V239','Nhân viên nhà ga',4,'难怪呢！你不用出站，下一站下车，对面站台坐二号线就可以直达啦。','nán guài ne！ nǐ bù yòng chū zhàn， xià yī zhàn xià chē， duì miàn zhàn tái zuò èr hào xiàn jiù kě yǐ zhí dá la。','Thảo nào! Em không cần ra khỏi ga đâu, xuống ở trạm tiếp theo, sang sân ga đối diện đi tuyến số 2 là tới thẳng luôn nhé.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_05','V239','Nguyễn Minh',5,'好的，那我不用重新买票吧？','hǎo de， nà wǒ bù yòng chóng xīn mǎi piào ba？','Vâng ạ, vậy em không cần mua vé lại đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_06','V239','Nhân viên nhà ga',6,'不用的，站内换乘都免费的，放心坐吧。','bù yòng de， zhàn nèi huàn chéng dōu miǎn fèi de， fàng xīn zuò ba。','Không cần đâu, đổi chuyến trong ga là miễn phí, em cứ yên tâm lên tàu nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_07','V239','Nguyễn Minh',7,'太谢谢您了，真是帮大忙了！','tài xiè xiè nín le， zhēn shì bāng dà máng le！','Em cảm ơn chị nhiều lắm, chị giúp em một việc lớn thật đó!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_08','V239','Nhân viên nhà ga',8,'不客气，下次看清楚方向再上车就好啦。','bú kè qì， xià cì kàn qīng chǔ fāng xiàng zài shàng chē jiù hǎo la。','Không có gì, lần sau em nhớ xem kỹ hướng trước khi lên tàu nhé.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT240','S11','Nhận hàng giao COD, đối chiếu thông tin','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V240','SIT240','P1','twist','tuy_y','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_01','V240','Shipper',1,'你好，是阮明吧？你的到付快递到啦，是被褥和厨具对吧？','nǐ hǎo， shì ruǎn míng ba？ nǐ de dào fù kuài dì dào la， shì bèi rù hé chú jù duì ba？','Chào bạn, có phải Nguyễn Minh không? Kiện hàng thu tiền hộ của bạn tới rồi nè, là chăn ga gối và đồ bếp đúng không?','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_02','V240','Nguyễn Minh',2,'对的，麻烦你帮我核对一下信息哈！手机号是尾号3621没错吧？','duì de， má fán nǐ bāng wǒ hé duì yī xià xìn xī hā！ shǒu jī hào shì wěi hào 3621 méi cuò ba？','Đúng rồi, phiền anh kiểm tra lại thông tin giúp em nha! Số điện thoại đuôi 3621 phải không ạ?','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_03','V240','Shipper',3,'没错的！地址也是学校留学生宿舍。运费一共28块哦。','méi cuò de！ dì zhǐ yě shì xué xiào liú xué shēng sù shè。 yùn fèi yī gòng 28 kuài ó。','Đúng rồi đó! Địa chỉ cũng là ký túc xá lưu học sinh của trường. Tiền ship tổng cộng là 28 tệ nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_04','V240','Nguyễn Minh',4,'咦？我看页面预估是22块，怎么多了6块呀？','yí？ wǒ kàn yè miàn yù gū shì 22 kuài， zěn me duō le 6 kuài ya？','Ơ? Em thấy trên app dự tính là 22 tệ mà, sao lại dư 6 tệ vậy ạ?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_05','V240','Shipper',5,'你这个被子超重啦，超重部分需要补运费，平台预估不准的。','nǐ zhè ge bèi zi chāo zhòng la， chāo zhòng bù fèn xū yào bǔ yùn fèi， píng tái yù gū bù zhǔn de。','Cái chăn của bạn nặng quá cân rồi, phần vượt cân phải tính thêm phí, ứng dụng dự tính không chuẩn đâu.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_06','V240','Nguyễn Minh',6,'原来是这样，那没问题，我扫码付钱吧。','yuán lái shì zhè yàng， nà méi wèn tí， wǒ sǎo mǎ fù qián ba。','Ra là vậy, thế thì không sao, để em quét mã trả tiền nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_07','V240','Shipper',7,'好嘞！付完我给你签收，东西都完好着呢，你可以检查一下。','hǎo lei！ fù wán wǒ gěi nǐ qiān shōu， dōng xī dōu wán hǎo zhe ne， nǐ kě yǐ jiǎn chá yī xià。','Được rồi đó! Trả xong anh ký nhận cho bạn, đồ đạc còn nguyên vẹn hết, bạn kiểm tra thử xem.','AM08') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_08','V240','Nguyễn Minh',8,'不用检查啦，谢谢你辛苦跑一趟！','bù yòng jiǎn chá la， xiè xiè nǐ xīn kǔ pǎo yī tàng！','Không cần kiểm tra đâu ạ, cảm ơn anh vất vả chạy một chuyến nhé!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT241','S12','Gọi món ở nhà ăn, xin không cay','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V241','SIT241','P1','suon_se','tuy_y','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_01','V241','Nhân viên nhà ăn',1,'同学，今天想吃点什么呀？米饭还是面条？','tóng xué， jīn tiān xiǎng chī diǎn shén me ya？ mǐ fàn hái shì miàn tiáo？','Em ơi, hôm nay muốn ăn gì nào? Cơm hay mì?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_02','V241','Nguyễn Minh',2,'阿姨，我要一份番茄炒蛋盖饭，谢谢！','ā yí， wǒ yào yī fèn fān qié chǎo dàn gài fàn， xiè xiè！','Cô ơi, cho con một suất cơm trứng chiên cà chua, cảm ơn cô!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_03','V241','Nhân viên nhà ăn',3,'好嘞！要不要加点配菜？青菜和土豆都新鲜的。','hǎo lei！ yào bù yào jiā diǎn pèi cài？ qīng cài hé tǔ dòu dōu xīn xiān de。','Được rồi đó! Có muốn thêm chút món phụ không? Rau xanh với khoai tây đều tươi cả.','AM08') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_04','V241','Nguyễn Minh',4,'不用啦阿姨！麻烦您一定不要放辣哦，我完全吃不了辣的。','bù yòng la ā yí！ má fán nín yí dìng bú yào fàng là ó， wǒ wán quán chī bù liǎo là de。','Thôi khỏi cô ơi! Phiền cô nhất định đừng cho cay nha, con hoàn toàn không ăn được cay đâu.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_05','V241','Nhân viên nhà ăn',5,'放心吧！我记住啦，给你做清淡口味的。','fàng xīn ba！ wǒ jì zhù la， gěi nǐ zuò qīng dàn kǒu wèi de。','Yên tâm đi! Cô nhớ rồi, làm cho con phần vị thanh đạm nhé.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_06','V241','Nguyễn Minh',6,'太好啦，谢谢阿姨！','tài hǎo la， xiè xiè ā yí！','Tuyệt quá, con cảm ơn cô!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_07','V241','Nhân viên nhà ăn',7,'小事一桩！马上就好，你稍微等一下哈。','xiǎo shì yī zhuāng！ mǎ shàng jiù hǎo， nǐ shāo wēi děng yí xià hā。','Chuyện nhỏ thôi! Xong ngay đây, con đợi một chút nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT242','S13','Xin nghỉ vì thủy thổ bất phục, nhờ bạn cùng phòng thông cảm','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V242','SIT242','P1','suon_se','tuy_y','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung',NULL) ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_01','V242','Nguyễn Minh',1,'宇哥，我这两天有点难受，想跟你说个事呢。','yǔ gē， wǒ zhè liǎng tiān yǒu diǎn nán shòu， xiǎng gēn nǐ shuō gè shì ne。','Vũ ơi, mấy hôm nay em thấy hơi khó chịu, muốn nói với anh một chuyện.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_02','V242','Lâm Vũ',2,'怎么了？你看着气色不太好，是不舒服吗？','zěn me le？ nǐ kàn zhe qì sè bù tài hǎo， shì bù shū fú ma？','Sao vậy? Nhìn sắc mặt em không được tốt lắm, khó chịu trong người à?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_03','V242','Nguyễn Minh',3,'应该是水土不服，晚上总睡不好，白天上课特别困。','yīng gāi shì shuǐ tǔ bù fú， wǎn shàng zǒng shuì bù hǎo， bái tiān shàng kè tè bié kùn。','Chắc là do chưa quen thủy thổ, tối cứ ngủ không ngon, ban ngày đi học lại buồn ngủ kinh khủng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_04','V242','Lâm Vũ',4,'难怪你这两天都没怎么说话！那你打算怎么办呀？','nán guài nǐ zhè liǎng tiān dōu méi zěn me shuō huà！ nà nǐ dǎ suàn zěn me bàn ya？','Thảo nào mấy hôm nay em ít nói hẳn! Vậy em định làm sao đây?','AM01') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
